// The branded illustration set — isometric scenes for property specs. Each
// hides the BalkanEstate two-tower mark somewhere small.
//
// The SVGs are generated by scripts/illustrations/generate.mjs into
// public/images/illustrations; edit the drawings there, not the files.

import React from 'react';
import type { SPEC_ILLUSTRATIONS } from './names.generated';

export type SpecIllustrationName = (typeof SPEC_ILLUSTRATIONS)[number];

interface IllustrationProps<N extends string> {
  name: N;
  className?: string;
}

/**
 * Decorative only: every place that shows one also prints the label next to
 * it, so the image is hidden from assistive technology.
 */
export const SpecIllustration: React.FC<IllustrationProps<SpecIllustrationName>> = ({ name, className }) => (
  <img
    src={`/images/illustrations/spec/${name}.svg`}
    alt=""
    aria-hidden="true"
    draggable={false}
    loading="lazy"
    decoding="async"
    className={`object-contain select-none ${className ?? ''}`}
  />
);
